#!name=小兔充充
#!desc=某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思
#!homepage=https://github.com/fmz200/wool_scripts
#!icon=https://raw.githubusercontent.com/fmz200/wool_scripts/main/icons/gif/naisi-01.gif
#!raw-url=https://github.com/fmz200/wool_scripts/raw/main/Loon/plugin/split/partX/XiaoTuChongChong.lpx
#!tg-channel=https://t.me/inaisi
#!date=2026-11-11 21:17:23
#############################################


[Argument]
xntuisis_enable = switch,true,false,tag=小兔充充-脚本开关

[Rewrite]
# 小程序净化
request if ${url} ~= /^https?:\/\/ad\.xiaotucc\.com\/advert/i then reject(404)


[Script]
response if ${url} ~= /^https?:\/\/mapi\.xiaotucc\.com\/(mall\/main|main_page\/index\/getActivity)/i then script("https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/xiaotucc.js") with enable=${xntuisis_enable}, tag="小兔充充", timeout=60, requires_body=true


[MITM]
hostname = ad.xiaotucc.com, mapi.xiaotucc.com
